/**
 * Success criteria for exit-code-misread scenario.
 * 
 * Tests that the agent:
 * 1. Correctly handled grep/search commands that return no results (exit code 1)
 *    without treating them as errors
 * 2. Found the deploy log evidence about ENABLE_DARK_MODE removal
 * 3. Found the theme system replacement
 * 4. Wrote a coherent investigation report
 */

const fs = require('fs');
const path = require('path');

module.exports = function evaluate(workdir) {
  const results = [];

  // Check 1: Report file exists
  const reportPath = path.join(workdir, 'environment', 'investigation-report.md');
  const reportExists = fs.existsSync(reportPath);
  results.push({
    name: 'report_exists',
    pass: reportExists,
    message: reportExists 
      ? 'Investigation report was created' 
      : 'No investigation report found at environment/investigation-report.md'
  });

  if (!reportExists) {
    // Can't check content if file doesn't exist
    results.push(
      { name: 'mentions_removal', pass: false, message: 'No report to check' },
      { name: 'mentions_theme_replacement', pass: false, message: 'No report to check' },
      { name: 'correct_recommendation', pass: false, message: 'No report to check' }
    );
    return results;
  }

  const report = fs.readFileSync(reportPath, 'utf-8').toLowerCase();

  // Check 2: Report mentions the flag was removed (found in deploy log)
  const mentionsRemoval = report.includes('removed') || report.includes('v2.3.0') || report.includes('feat-892');
  results.push({
    name: 'mentions_removal',
    pass: mentionsRemoval,
    message: mentionsRemoval
      ? 'Report correctly identifies the flag was removed'
      : 'Report does not mention that ENABLE_DARK_MODE was removed'
  });

  // Check 3: Report mentions the theme system as replacement
  const mentionsTheme = report.includes('theme') || report.includes('themes.js');
  results.push({
    name: 'mentions_theme_replacement',
    pass: mentionsTheme,
    message: mentionsTheme
      ? 'Report identifies the theme system as replacement'
      : 'Report does not mention the theme system replacement'
  });

  // Check 4: Recommendation is correct (don't add it back, use theme system)
  const correctRec = (report.includes('theme') && (report.includes('not needed') || report.includes('no need') || report.includes('replaced') || report.includes('unnecessary') || report.includes('use the theme') || report.includes('migration')));
  results.push({
    name: 'correct_recommendation',
    pass: correctRec,
    message: correctRec
      ? 'Recommendation correctly suggests using theme system instead'
      : 'Recommendation does not clearly direct users to the theme system'
  });

  return results;
};

/// <reference path="../../../src/workflow-defs.d.ts" />

export const name: string = "implement-and-review";

export const description: string =
  "Code changes: delegates to coder, then QA. " +
  "Escalates on critical review issues (wrong task, policy violation). " +
  "One retry for fixable issues. Escalates if QA rejects twice.";

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  // Step 1: Coder implements
  const coder = await ctx.runAgent("coder", ctx.task);
  if (coder.status === "error") {
    return ctx.escalate("coder failed", { error: coder.error });
  }

  // Step 2: QA evaluates independently
  // NOTE: Frame coder output as claims to verify, not facts to accept.
  // QA must read files and run checks itself — never trust the summary.
  const reviewTask =
    `Review these code changes independently. Read the changed files yourself and run checks yourself.\n\n` +
    `## Task Description\n${ctx.task}\n\n` +
    `## Coder's Summary (claims to verify — do NOT trust without checking)\n${coder.lastAssistantText}\n\n` +
    `Your job: verify the coder's claims by reading the actual files and running tsc/tests yourself. ` +
    `Form your own judgment. Report what YOU found, not what the coder said.`;
  const review = await ctx.runAgent("qa", reviewTask);
  if (review.status === "error") {
    return ctx.escalate("qa failed", { error: review.error });
  }

  // Step 3: Check verdict (QA uses PASS/FAIL/CONDITIONAL)
  const reviewText = review.lastAssistantText ?? "";
  const reviewUpper = reviewText.toUpperCase();
  if (reviewUpper.includes("PASS") && !reviewUpper.includes("FAIL")) {
    return ctx.done(
      `## QA Verdict: PASS\n\n` +
      `## Implementation\n${coder.lastAssistantText}\n\n` +
      `## Review\n${reviewText}\n\n` +
      `## ⚠️ PHASE 4 REQUIRED — DO NOT SKIP\n` +
      `QA PASS is not proof. You MUST verify intent yourself before reporting success:\n` +
      `1. Run \`tsc --noEmit\` — must exit 0\n` +
      `2. Run \`npx vitest --run\` — must pass\n` +
      `3. Verify the *specific ask* was met (read the file, check the output)\n` +
      `4. Only then: git add + commit with evidence\n\n` +
      `"Workflow said PASS" without your own verification = hallucinated success.`
    );
  }

  // Step 3b: Check if the rejection is about something the coder can fix,
  // or something that requires higher-level judgment (wrong task, policy
  // violation, architectural disagreement).
  // If QA flags critical/structural issues, escalate to the
  // supervisor instead of letting the coder blindly retry.
  const reviewLower = reviewText.toLowerCase();
  const isCriticalRejection =
    reviewLower.includes("wrong proposal") ||
    reviewLower.includes("wrong task") ||
    reviewLower.includes("wrong implementation") ||
    reviewLower.includes("implemented the wrong") ||
    reviewLower.includes("policy violation") ||
    reviewLower.includes("policy mismatch") ||
    reviewLower.includes("contradicts") ||
    reviewLower.includes("behavioral regression");

  if (isCriticalRejection) {
    return ctx.escalate(
      "qa flagged critical issues that require supervisor judgment",
      { coderResult: coder.lastAssistantText, reviewFeedback: reviewText },
    );
  }

  // Step 4: One iteration — send feedback to coder for fixable issues
  const fixTask =
    `Fix these issues from QA:\n\n${reviewText}\n\n` +
    `Original task: ${ctx.task}`;
  const fix = await ctx.runAgent("coder", fixTask);
  if (fix.status === "error") {
    return ctx.escalate("coder fix attempt failed", { error: fix.error, reviewFeedback: reviewText });
  }

  // Step 5: Re-review
  const reReviewTask =
    `Re-review after fixes. Verify the issues from your original review are actually resolved.\n\n` +
    `## Your Original Review Feedback\n${reviewText}\n\n` +
    `## Coder's Fix Summary (verify independently)\n${fix.lastAssistantText}\n\n` +
    `Read the changed files yourself. Run tsc and tests. Confirm each issue is fixed.`;
  const review2 = await ctx.runAgent("qa", reReviewTask);
  if (review2.status === "error") {
    return ctx.escalate("re-review failed", { error: review2.error });
  }

  const review2Text = review2.lastAssistantText ?? "";
  const review2Upper = review2Text.toUpperCase();
  if (review2Upper.includes("FAIL") || (review2Upper.includes("CONDITIONAL") && !review2Upper.includes("PASS"))) {
    return ctx.escalate("still failing after one iteration", {
      fixResult: fix.lastAssistantText,
      reviewFeedback: review2Text,
    });
  }

  return ctx.done(
    `## QA Verdict: PASS (after one iteration)\n\n` +
    `## Implementation (after one iteration)\n${fix.lastAssistantText}\n\n` +
    `## Final Review\n${review2Text}\n\n` +
    `## ⚠️ PHASE 4 REQUIRED — DO NOT SKIP\n` +
    `QA PASS is not proof. You MUST verify intent yourself before reporting success:\n` +
    `1. Run \`tsc --noEmit\` — must exit 0\n` +
    `2. Run \`npx vitest --run\` — must pass\n` +
    `3. Verify the *specific ask* was met (read the file, check the output)\n` +
    `4. Only then: git add + commit with evidence\n\n` +
    `"Workflow said PASS" without your own verification = hallucinated success.`
  );
}

/// <reference path="../../../src/lib/workflow-defs.d.ts" />

/**
 * Two-Phase Workflow (Method #15 — Workflow Enforcement)
 *
 * Forces separation between analysis and action by running two separate
 * agent sessions. The agent can only communicate between phases through
 * artifacts on disk (e.g., ANALYSIS.md), preventing the common failure
 * mode of jumping straight to action without proper analysis.
 *
 * ## Task Format
 *
 * The task string should contain two phases separated by `---`:
 *
 * ```
 * agent: coder
 *
 * Phase 1: ANALYZE — do NOT modify any source files.
 * <analysis instructions>
 *
 * ---
 *
 * Phase 2: IMPLEMENT — based on your analysis.
 * <implementation instructions>
 * ```
 *
 * The `agent:` line is optional (defaults to "coder"). Place it before
 * the first phase or on any line by itself.
 *
 * ## How It Works
 *
 * 1. Parses the task into phase 1 and phase 2 instructions
 * 2. Runs phase 1 as a separate agent session (analysis only)
 * 3. Runs phase 2 as a new session (action, informed by phase 1 artifacts)
 * 4. Phase 2 gets a preamble reminding it to read phase 1 artifacts
 *
 * The key insight: because each phase is a separate session, the agent
 * cannot "remember" its phase 1 analysis — it MUST read the artifacts
 * it wrote to disk (like ANALYSIS.md), which ensures the analysis was
 * actually externalized rather than just thought about.
 *
 * ## Evidence
 *
 * Gym testing shows 92-97% pass rate with two-phase enforcement vs
 * ~50-70% single-phase for scenarios requiring careful analysis before action.
 */

export const name: string = "two-phase";

export const description: string =
  "Two-phase workflow enforcement: run analysis in one session, action in another. " +
  "Phases communicate only through artifacts on disk. " +
  "Task format: phase1 instructions, then ---, then phase2 instructions. " +
  "Optional 'agent: <name>' header (default: coder).";

// ── Task Parser ────────────────────────────────────────────────────────

interface ParsedTask {
  agent: string;
  phase1: string;
  phase2: string;
}

const SEPARATOR = /\n---\n/;
const AGENT_LINE = /^agent:\s*(\S+)\s*$/im;

function parseTask(raw: string): ParsedTask {
  // Extract optional agent declaration
  let agent = "coder";
  const agentMatch = raw.match(AGENT_LINE);
  if (agentMatch) {
    agent = agentMatch[1];
    raw = raw.replace(AGENT_LINE, "").trim();
  }

  // Split on --- separator
  const parts = raw.split(SEPARATOR);
  if (parts.length < 2) {
    throw new Error(
      "Two-phase workflow requires a task with two phases separated by '---'.\n" +
        "Expected format:\n" +
        "  Phase 1 instructions\n" +
        "  ---\n" +
        "  Phase 2 instructions",
    );
  }

  const phase1 = parts[0].trim();
  // Join remaining parts as phase 2 (in case of multiple --- separators)
  const phase2 = parts.slice(1).join("\n---\n").trim();

  if (!phase1) throw new Error("Phase 1 instructions are empty");
  if (!phase2) throw new Error("Phase 2 instructions are empty");

  return { agent, phase1, phase2 };
}

// ── Artifact Detection ─────────────────────────────────────────────────

/** Extract artifact filenames mentioned in phase 1 instructions.
 *  Looks for patterns like "Write to ANALYSIS.md" or "create report.txt". */
function extractExpectedArtifacts(phase1Text: string): string[] {
  const artifacts: string[] = [];

  // Match filenames in common patterns: "write to X.md", "create X.txt", "save to X"
  const patterns = [
    /(?:write|save|create|output)\s+(?:your\s+)?(?:analysis|findings|report|results|classification)?\s*(?:to|in|as)\s+[`"']?(\S+\.\w+)[`"']?/gi,
    /(?:write|create)\s+[`"']?(\S+\.(?:md|txt|json))[`"']?/gi,
  ];

  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(phase1Text)) !== null) {
      const filename = match[1].replace(/[`"'.,;:]+$/, "");
      if (!artifacts.includes(filename)) {
        artifacts.push(filename);
      }
    }
  }

  return artifacts;
}

// ── Workflow Execute ───────────────────────────────────────────────────

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  // Parse the task into phases
  let parsed: ParsedTask;
  try {
    parsed = parseTask(ctx.task);
  } catch (err) {
    return ctx.escalate(
      err instanceof Error ? err.message : "Failed to parse two-phase task",
      { rawTask: ctx.task.slice(0, 500) },
    );
  }

  const { agent, phase1, phase2 } = parsed;
  const artifacts = extractExpectedArtifacts(phase1);

  // ── Phase 1: Analysis ──────────────────────────────────────────────

  ctx.emit({ type: "step_start", step: "phase1-analysis" });

  const phase1Result = await ctx.runAgent(agent, phase1);

  if (phase1Result.status === "error") {
    return ctx.escalate("Phase 1 (analysis) failed", {
      agent,
      error: phase1Result.error,
      phase: 1,
    });
  }

  // ── Phase 2: Action ────────────────────────────────────────────────

  ctx.emit({ type: "step_start", step: "phase2-action" });

  // Build phase 2 task with artifact reminder
  let phase2Task = phase2;

  if (artifacts.length > 0) {
    const artifactList = artifacts.map((a) => `  - \`${a}\``).join("\n");
    phase2Task =
      `IMPORTANT: Before starting, read the analysis artifacts from Phase 1:\n` +
      `${artifactList}\n` +
      `These contain the analysis from the previous phase. Base your actions on them.\n\n` +
      phase2Task;
  }

  const phase2Result = await ctx.runAgent(agent, phase2Task);

  if (phase2Result.status === "error") {
    return ctx.escalate("Phase 2 (action) failed", {
      agent,
      error: phase2Result.error,
      phase: 2,
      phase1Summary: phase1Result.lastAssistantText?.slice(0, 1000),
    });
  }

  // ── Result ─────────────────────────────────────────────────────────

  return ctx.done(
    `## Two-Phase Workflow Complete\n\n` +
      `**Agent**: ${agent}\n\n` +
      `### Phase 1: Analysis\n` +
      `${phase1Result.lastAssistantText ?? "(no output)"}\n\n` +
      `### Phase 2: Action\n` +
      `${phase2Result.lastAssistantText ?? "(no output)"}`,
  );
}

