/// <reference path="../../../src/lib/workflow-defs.d.ts" />

/**
 * investigate-thorough workflow — Two-Phase Investigation Enforcement
 *
 * Prevents FM-2.4 SILENT_FAIL: agents misinterpreting empty search results
 * (grep exit code 1) as "clean" and stopping investigation too early.
 *
 * Phase 1: GATHER — Agent searches ALL specified locations and records raw
 * findings to an evidence file. Must report on EVERY location, even if
 * empty. Cannot skip locations because earlier searches returned no results.
 *
 * Phase 2: ANALYZE — Agent reads the evidence file and writes the final
 * report/deliverable. Separated session ensures analysis is based on
 * complete evidence, not premature conclusions.
 *
 * Task format:
 *   The task description as-is. The workflow wraps it in two phases
 *   automatically. Optional `workdir:` line to specify the working directory.
 *
 * Based on Method #15 (Workflow Enforcement) — proven ~92-97% pass rate.
 */

export const name: string = "investigate-thorough";

export const description: string =
  "Two-phase investigation: Phase 1 gathers evidence from ALL sources " +
  "(no conclusions allowed), Phase 2 analyzes evidence and writes report. " +
  "Prevents SILENT_FAIL where empty search results cause premature stop.";

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  const task = ctx.task.trim();

  // Extract optional workdir
  const workdirMatch = task.match(/^workdir:\s*(.+)$/m);
  const workdir = workdirMatch ? workdirMatch[1].trim() : "environment";
  const cleanTask = task.replace(/^workdir:\s*.+$/m, "").trim();

  // ── Phase 1: GATHER EVIDENCE ────────────────────────────────────────

